//! T02 contract battery (M214-es3jvw S01).
//!
//! Executable core of `prd/architecture/npa-analysis-jsonl-contract.md`:
//! a valid source-to-analysis coordinate resolves to the exact UTF-8 slice of
//! the pinned parent; the block-to-fragment rule is explicit; the document
//! version triple and the three token views stay separate.
//!
//! The fixture `t7 = "см. ст. 5"` mirrors T01 §11 P1; byte offsets below are a
//! handwritten oracle over that literal, never generated by the code under
//! test. The token-view expectations mirror T01 §11 P2 and the ADR-0028 dual
//! tokenizer (covering `Abbrev{st}`, alphabetic `ст`, no covering word).

use ln_decode::analysis_source_mapping::{
    CoordinateKind, EnvelopeLineKind, EnvelopeLineShape, MappingRefusal, MappingRefusalKind,
    SourceIdentity, SourceMapping, TokenView, check_coordinate_kind, check_envelope_shape,
    check_token_span, check_token_view,
};
use ln_decode::document_context::DocumentVersionRef;
use ln_decode::lexer::{self, TokenKind};
use ln_decode::npa_anchor::LocalSpan;
use ln_decode::reader_contract::{FragmentRef, ReaderFragmentSpan};

const FRAGMENT_T7: &str = "см. ст. 5";
const FRAGMENT_T4: &str = "статьи 5";

/// A 64-char lowercase hex string made of one repeated digit.
fn hex64(fill: u8) -> String {
    (0..64).map(|_| fill as char).collect()
}

fn identity(fill: u8, sealed: bool) -> SourceIdentity {
    SourceIdentity::try_new(
        hex64(fill),
        FRAGMENT_T7.len() as u64,
        "law-nexus/source-package-model/v1".to_string(),
        sealed.then_some(hex64(b'1')),
        sealed.then_some(hex64(b'2')),
    )
    .expect("identity must be well formed")
}

fn version(source_revision: &str) -> DocumentVersionRef {
    DocumentVersionRef::try_new(
        "doc-version-1".to_string(),
        source_revision.to_string(),
        "reader_wordml_profile/v1".to_string(),
    )
    .expect("version triple must be well formed")
}

fn mapping() -> SourceMapping {
    let mut mapping = SourceMapping::new(identity(b'a', false), version("rev-1"));
    mapping
        .pin_fragment(FragmentRef::new("t7"), FRAGMENT_T7, &identity(b'a', false))
        .expect("t7 belongs to document A");
    mapping
        .pin_fragment(FragmentRef::new("t4"), FRAGMENT_T4, &identity(b'a', false))
        .expect("t4 belongs to document A");
    mapping
        .map_block(0, FragmentRef::new("t7"))
        .expect("block 0 maps to t7");
    mapping
}

#[test]
fn p1_valid_fragment_span_resolves_to_original_utf8_slice() {
    let mapping = mapping();
    let span = ReaderFragmentSpan::new(FragmentRef::new("t7"), 6, 13);
    let resolved = mapping
        .resolve_fragment_span(&span)
        .expect("half-open range [6, 13) is valid on t7");
    assert_eq!(resolved.fragment, FragmentRef::new("t7"));
    assert_eq!((resolved.start, resolved.end), (6, 13));
    assert_eq!(
        mapping.slice(&resolved).expect("resolved span slices"),
        "ст. 5"
    );
    assert_eq!(&FRAGMENT_T7[6..13], "ст. 5");
    assert_eq!(FRAGMENT_T7.len(), 13);
}

#[test]
fn p1b_local_block_span_resolves_through_the_block_fragment_rule() {
    let mapping = mapping();
    let resolved = mapping
        .resolve_local_span(LocalSpan {
            block: 0,
            start: 6,
            end: 13,
        })
        .expect("block 0 maps to t7 and the range is valid");
    assert_eq!(resolved.fragment, FragmentRef::new("t7"));
    assert_eq!(
        mapping.slice(&resolved).expect("resolved span slices"),
        "ст. 5"
    );
}

#[test]
fn whole_fragment_span_resolves_to_full_text() {
    let mapping = mapping();
    let span = ReaderFragmentSpan::new(FragmentRef::new("t4"), 0, FRAGMENT_T4.len());
    let resolved = mapping
        .resolve_fragment_span(&span)
        .expect("whole-fragment range is valid");
    assert_eq!(
        mapping.slice(&resolved).expect("resolved span slices"),
        "статьи 5"
    );
    assert_eq!(FRAGMENT_T4.len(), 14);
}

#[test]
fn p2_token_views_are_distinct_and_not_interchangeable() {
    let text = "ст. 5";

    // Covering (`lex`): the abbreviation lexeme "ст." is one `Abbrev{st}`.
    let abbrev = lexer::lex(text)
        .into_iter()
        .find(|token| token.kind == TokenKind::Abbrev)
        .expect("covering lexer mints Abbrev{st}");
    assert_eq!((abbrev.span.start(), abbrev.span.end()), (0, 5));
    assert_eq!(check_token_span(text, TokenView::Covering, 0, 5), Ok(()));

    // Alphabetic splitter: the stem "ст" spans two cyrillic code points (4 bytes).
    assert_eq!(check_token_span(text, TokenView::Alphabetic, 0, 4), Ok(()));

    // Covering-word projection: the abbreviation stem is absent by construction.
    assert_eq!(
        check_token_span(text, TokenView::CoveringWord, 0, 4)
            .expect_err("Abbrev stem is not a covering word")
            .kind(),
        MappingRefusalKind::TokenViewMismatch
    );

    // Cross-view substitution is refused (T01 §12 H7 shape).
    assert_eq!(
        check_token_view(TokenView::CoveringWord, TokenView::Alphabetic)
            .expect_err("a morphology outcome cannot declare the alphabetic view")
            .kind(),
        MappingRefusalKind::TokenViewMismatch
    );
    assert_eq!(
        check_token_view(TokenView::Covering, TokenView::Covering),
        Ok(())
    );

    // A full word is visible to both word views.
    let word = "статьи 5";
    assert_eq!(
        check_token_span(word, TokenView::CoveringWord, 0, 12),
        Ok(())
    );
    assert_eq!(check_token_span(word, TokenView::Alphabetic, 0, 12), Ok(()));
}

#[test]
fn document_version_and_parent_citation_are_identity_checks() {
    let mapping = mapping();
    assert_eq!(mapping.check_document_version(&version("rev-1")), Ok(()));
    assert_eq!(
        mapping.check_parent_citation(&identity(b'a', false)),
        Ok(())
    );
    assert_eq!(mapping.fragment_count(), 2);
    assert_eq!(mapping.envelope().source_sha256, hex64(b'a'));
    assert_eq!(mapping.version().document_version_ref(), "doc-version-1");
}

#[test]
fn decoded_coordinate_kinds_are_supported() {
    assert_eq!(
        check_coordinate_kind(CoordinateKind::LocalBlockSpan),
        Ok(())
    );
    assert_eq!(check_coordinate_kind(CoordinateKind::FragmentSpan), Ok(()));
}

#[test]
fn valid_envelope_shape_has_manifest_policies_records_footer() {
    let lines = [
        EnvelopeLineShape::new(EnvelopeLineKind::Manifest, 10),
        EnvelopeLineShape::new(EnvelopeLineKind::Policies, 10),
        EnvelopeLineShape::new(EnvelopeLineKind::Record, 10),
        EnvelopeLineShape::new(EnvelopeLineKind::Record, 10),
        EnvelopeLineShape::new(EnvelopeLineKind::Footer, 10),
    ];
    assert_eq!(check_envelope_shape(&lines), Ok(()));
}

#[test]
fn refusal_display_and_error_trait_are_closed() {
    let refusal: MappingRefusal = check_coordinate_kind(CoordinateKind::CharacterOffset)
        .expect_err("character offsets are not byte coordinates");
    assert_eq!(refusal.kind(), MappingRefusalKind::UnsupportedMapping);
    assert_eq!(refusal.kind().as_str(), "unsupported_mapping");
    assert!(!refusal.detail().is_empty());
    let _: &dyn std::error::Error = &refusal;
}
